/* Modern Minimal Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="modern-minimal-light"] {
  --background: #ffffff;
  --foreground: #333333;
  --card: #ffffff;
  --card-foreground: #333333;
  --popover: #ffffff;
  --popover-foreground: #333333;
  --primary: #3981f6;
  --primary-foreground: #ffffff;
  --secondary: #f5f5f5;
  --secondary-foreground: #4b5666;
  --muted: #f8f8f8;
  --muted-foreground: #6c727e;
  --accent: #def2ff;
  --accent-foreground: #1e3a8b;
  --destructive: #f14444;
  --destructive-foreground: #ffffff;
  --border: #e4e8ef;
  --input: #e4e8ef;
  --ring: #3981f6;
  --chart-1: #3981f6;
  --chart-2: #2463ef;
  --chart-3: #1d4eda;
  --chart-4: #1d3fad;
  --chart-5: #1e3a8b;
  --radius: 0.375rem;
  --sidebar: #f8f8f8;
  --sidebar-foreground: #333333;
  --sidebar-primary: #3981f6;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #def2ff;
  --sidebar-accent-foreground: #1e3a8b;
  --sidebar-border: #e4e8ef;
  --sidebar-ring: #3981f6;
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="modern-minimal-dark"] {
  --background: #161616;
  --foreground: #e4e4e4;
  --card: #262626;
  --card-foreground: #e4e4e4;
